+const { HEADER_FONT, BODY_FONT, addPageBadge, addTopRule } = require("./theme");
+
+const slideConfig = {
+  type: "content",
+  index: 3,
+  title: "hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score"
+};
+
+// Top 5 from the source brief table
+const rows = [
+  {
+    rank: "#1",
+    repo: "NousResearch/hermes-agent",
+    stars: 1347,
+    forks: 101,
+    pushes: 42,
+    prs: 78
+  },
+  {
+    rank: "#2",
+    repo: "safishamsi/graphify",
+    stars: 742,
+    forks: 50,
+    pushes: 6,
+    prs: 5
+  },
+  {
+    rank: "#3",
+    repo: "VoltAgent/awesome-design-md",
+    stars: 615,
+    forks: 48,
+    pushes: 1,
+    prs: 0
+  },
+  {
+    rank: "#4",
+    repo: "JuliusBrussee/caveman",
+    stars: 300,
+    forks: 11,
+    pushes: 1,
+    prs: 1
+  },
+  {
+    rank: "#5",
+    repo: "shanraisshan/claude-code-best-practice",
+    stars: 304,
+    forks: 23,
+    pushes: 0,
+    prs: 0
+  }
+];
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+  addTopRule(slide, theme);
+
+  slide.addText(slideConfig.title, {
+    x: 0.6,
+    y: 0.35,
+    w: 8.8,
+    h: 0.55,
+    fontFace: HEADER_FONT,
+    fontSize: 32,
+    bold: true,
+    color: theme.primary
+  });
+
+  // Table header
+  const x0 = 0.6;
+  const y0 = 1.2;
+  const tableW = 8.9;
+  const headerH = 0.42;
+  const rowH = 0.55;
+
+  slide.addShape(pres.ShapeType.roundRect, {
+    x: x0,
+    y: y0,
+    w: tableW,
+    h: headerH,
+    fill: { color: theme.primary },
+    line: { color: theme.primary }
+  });
+
+  const cols = [
+    { label: "Rank", w: 0.7 },
+    { label: "Repository", w: 4.2 },
+    { label: "Stars", w: 1.0 },
+    { label: "Forks", w: 1.0 },
+    { label: "Pushes", w: 1.0 },
+    { label: "PRs", w: 1.0 }
+  ];
+
+  let cx = x0;
+  for (const c of cols) {
+    slide.addText(c.label, {
+      x: cx,
+      y: y0 + 0.08,
+      w: c.w,
+      h: headerH,
+      fontFace: BODY_FONT,
+      fontSize: 12,
+      color: theme.bg,
+      bold: true,
+      align: c.label === "Repository" ? "left" : "center"
+    });
+    cx += c.w;
+  }
+
+  // Data rows
+  let y = y0 + headerH;
+  for (let i = 0; i < rows.length; i++) {
+    const r = rows[i];
+    const fill = i % 2 === 0 ? { color: theme.primary, transparency: 92 } : { color: theme.secondary, transparency: 90 };
+    slide.addShape(pres.ShapeType.rect, {
+      x: x0,
+      y,
+      w: tableW,
+      h: rowH,
+      fill,
+      line: { color: theme.primary, transparency: 70 }
+    });
+
+    // Emphasize #1
+    if (i === 0) {
+      slide.addShape(pres.ShapeType.rect, {
+        x: x0,
+        y,
+        w: 0.12,
+        h: rowH,
+        fill: { color: theme.light },
+        line: { color: theme.light }
+      });
+    }
+
+    const cells = [
+      { text: r.rank, w: 0.7, align: "center", bold: i === 0 },
+      { text: r.repo, w: 4.2, align: "left", bold: i === 0 },
+      { text: String(r.stars), w: 1.0, align: "center", bold: i === 0 },
+      { text: String(r.forks), w: 1.0, align: "center" },
+      { text: String(r.pushes), w: 1.0, align: "center" },
+      { text: String(r.prs), w: 1.0, align: "center" }
+    ];
+    cx = x0;
+    for (const c of cells) {
+      slide.addText(c.text, {
+        x: cx + (c.align === "left" ? 0.1 : 0),
+        y: y + 0.12,
+        w: c.w - (c.align === "left" ? 0.1 : 0),
+        h: rowH,
+        fontFace: BODY_FONT,
+        fontSize: 13,
+        color: theme.primary,
+        bold: !!c.bold,
+        align: c.align,
+        valign: "mid"
+      });
+      cx += c.w;
+    }
+    y += rowH;
+  }
+
+  // Simple horizontal bar chart for stars (to the right, compact)
+  const chartX = 0.6;
+  const chartY = 4.6;
+  slide.addText("Stars (relative)", {
+    x: chartX,
+    y: chartY,
+    w: 4.3,
+    h: 0.3,
+    fontFace: BODY_FONT,
+    fontSize: 12,
+    bold: true,
+    color: theme.primary
+  });
+
+  const maxStars = Math.max(...rows.map((r) => r.stars));
+  for (let i = 0; i < rows.length; i++) {
+    const r = rows[i];
+    const yy = chartY + 0.35 + i * 0.22;
+    const ww = (r.stars / maxStars) * 4.2;
+    slide.addShape(pres.ShapeType.roundRect, {
+      x: chartX,
+      y: yy,
+      w: 4.3,
+      h: 0.16,
+      fill: { color: theme.primary, transparency: 92 },
+      line: { color: theme.primary, transparency: 80 }
+    });
+    slide.addShape(pres.ShapeType.roundRect, {
+      x: chartX,
+      y: yy,
+      w: Math.max(0.08, ww),
+      h: 0.16,
+      fill: { color: i === 0 ? theme.light : theme.secondary },
+      line: { color: i === 0 ? theme.light : theme.secondary }
+    });
+  }
+
+  slide.addText("Metrics shown: Stars, Forks, Pushes, PRs (past 24h trending table)", {
+    x: 0.6,
+    y: 5.25,
+    w: 8.0,
+    h: 0.25,
+    fontFace: BODY_FONT,
+    fontSize: 11,
+    color: theme.primary,
+    transparency: 35
+  });
+  slide.addText("Source: ossinsight.io", {
+    x: 8.05,
+    y: 5.25,
+    w: 1.45,
+    h: 0.25,
+    fontFace: BODY_FONT,
+    fontSize: 11,
+    color: theme.primary,
+    transparency: 35,
+    align: "right"
+  });
+
+  addPageBadge(slide, theme, 3, 8);
+  return slide;
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
